//! Color adjustment operations — the `ColorSpace::ColorConverter` namespace.

use crate::hsl::{hsl_to_rgb, rgb_to_hsl};
use crate::rgb::Rgb;

/// Stateless collection of conversion helpers, standing in for the C++ class
/// whose members are all static.
pub struct ColorConverter;

impl ColorConverter {
    /// Scales a color's saturation by `factor`, leaving hue and lightness alone.
    ///
    /// The scaled saturation is clamped into `[0, 1]` with two one-sided
    /// comparisons rather than `f32::clamp`, because that is what preserves the
    /// C++ behavior at the extremes: an infinite saturation (from `max + min == 2`)
    /// clamps down to `1`, a negative one (from out-of-gamut input) clamps up to
    /// `0` and desaturates to flat lightness, and a `NaN` fails both comparisons
    /// and propagates through untouched.
    pub fn adjust_saturation(rgb: &Rgb, factor: f32) -> Rgb {
        let mut hsl = rgb_to_hsl(rgb);

        hsl.s *= factor;
        if hsl.s > 1.0 {
            hsl.s = 1.0;
        }
        if hsl.s < 0.0 {
            hsl.s = 0.0;
        }

        hsl_to_rgb(&hsl)
    }
}

