//! Reproduction of `std::ostream`'s default `float` formatting.
//!
//! A default-configured stream uses `defaultfloat` with precision 6, which is
//! `printf("%g", (double)value)`: six significant digits, `%e` style when the
//! decimal exponent falls outside `[-4, 6)` and `%f` style otherwise, with
//! trailing zeros — and a trailing point — removed in both cases.

/// Significant digits in a default-precision stream.
const PRECISION: usize = 6;

/// Formats a `f32` the way `std::cout << value` would.
///
/// The value is widened to `f64` first, mirroring the default argument
/// promotion the C++ stream performs; the widening is exact, so it only matters
/// for how the digits are generated.
pub fn cout_float(v: f32) -> String {
    let x = v as f64;

    // libstdc++ forwards the sign bit for both non-finite forms, so a negative
    // NaN prints as "-nan" — which is what the saturation math produces from
    // infinite input.
    if x.is_nan() {
        return if x.is_sign_negative() { "-nan" } else { "nan" }.to_string();
    }
    if x.is_infinite() {
        return if x.is_sign_negative() { "-inf" } else { "inf" }.to_string();
    }

    let (digits, exp) = round_to_significant(x);
    let sign = if x.is_sign_negative() { "-" } else { "" };

    // %g's style selection, with P = 6.
    let body = if exp < -4 || exp >= PRECISION as i32 {
        scientific(&digits, exp)
    } else {
        fixed(&digits, exp)
    };

    format!("{}{}", sign, body)
}

/// Rounds `|x|` to [`PRECISION`] significant digits.
///
/// Returns the digit string (always exactly [`PRECISION`] characters, the first
/// being the leading digit) and the decimal exponent `e` such that the value is
/// `d.ddddd * 10^e`.
///
/// The heavy lifting is delegated to the standard library's exact scientific
/// formatting, which rounds half to even off the true binary value — the same
/// rule glibc's `printf` applies.
fn round_to_significant(x: f64) -> (String, i32) {
    let s = format!("{:.*e}", PRECISION - 1, x.abs());

    // Shape is always "d.ddddde<exp>": one leading digit, a point, PRECISION-1
    // more digits, then an unpadded exponent.
    let (mantissa, exponent) = s.split_once('e').expect("std scientific format has an exponent");
    let digits: String = mantissa.chars().filter(|c| *c != '.').collect();
    let exp: i32 = exponent.parse().expect("std scientific exponent is an integer");

    (digits, exp)
}

/// Renders `%e` style: one leading digit, the rest as a fraction, and an
/// exponent that is signed and padded to at least two digits.
fn scientific(digits: &str, exp: i32) -> String {
    let mut out = String::new();
    out.push_str(&digits[..1]);

    let frac = trim_zeros(&digits[1..]);
    if !frac.is_empty() {
        out.push('.');
        out.push_str(frac);
    }

    out.push('e');
    out.push(if exp < 0 { '-' } else { '+' });
    out.push_str(&format!("{:02}", exp.unsigned_abs()));

    out
}

/// Renders `%f` style for an exponent already known to be in `[-4, PRECISION)`.
fn fixed(digits: &str, exp: i32) -> String {
    let (int_part, frac_part) = if exp >= 0 {
        // The point sits inside the digit string.
        let split = exp as usize + 1;
        (digits[..split].to_string(), digits[split..].to_string())
    } else {
        // Leading zeros push the digits below the point: 10^exp with exp <= -1
        // means -exp-1 zeros before the first significant digit.
        let mut frac = "0".repeat((-exp - 1) as usize);
        frac.push_str(digits);
        ("0".to_string(), frac)
    };

    let frac = trim_zeros(&frac_part);
    if frac.is_empty() {
        int_part
    } else {
        format!("{}.{}", int_part, frac)
    }
}

/// Drops trailing zeros, as `%g` does without the `#` flag.
fn trim_zeros(s: &str) -> &str {
    s.trim_end_matches('0')
}

