    let frac = trim_zeros(&digits[1..]);
    if !frac.is_empty() {
        out.push('.');
        out.push_str(frac);
    }

    out.push('e');
    out.push(if exp < 0 { '-' } else { '+' });
    out.push_str(&format!("{:02}", exp.unsigned_abs()));

    out
}

/// Renders `%f` style for an exponent already known to be in `[-4, PRECISION)`.
fn fixed(digits: &str, exp: i32) -> String {
    let (int_part, frac_part) = if exp >= 0 {
        // The point sits inside the digit string.
        let split = exp as usize + 1;
        (digits[..split].to_string(), digits[split..].to_string())
    } else {
        // Leading zeros push the digits below the point: 10^exp with exp <= -1
        // means -exp-1 zeros before the first significant digit.
        let mut frac = "0".repeat((-exp - 1) as usize);
        frac.push_str(digits);
