//! The modules are pulled in by path rather than through the library target so
//! that this file builds both ways — `rustc test9.rs` on its own, and
//! `cargo build --release` as the package's binary.

#[path = "src/converter.rs"]
mod converter;
#[path = "src/fmt.rs"]
mod fmt;
#[path = "src/hsl.rs"]
mod hsl;
#[path = "src/rgb.rs"]
mod rgb;
#[path = "src/stof.rs"]
mod stof;

use converter::ColorConverter;
use fmt::cout_float;
use rgb::Rgb;
use stof::stof;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let argc = args.len();

    let mut r = 0.5f32;
    let mut g = 0.6f32;
    let mut b = 0.7f32;
    let mut factor = 1.5f32;

    // Both channel triple and factor are all-or-nothing, keyed off argc exactly
    // as in the C++ source: a partial triple leaves every default in place.
    if argc > 3 {
        r = stof(&args[1]);
        g = stof(&args[2]);
        b = stof(&args[3]);
    }
    if argc > 4 {
        factor = stof(&args[4]);
    }

    let rgb = Rgb::new(r, g, b);
    let result = ColorConverter::adjust_saturation(&rgb, factor);

    println!(
        "{} {} {}",
        cout_float(result.r),
        cout_float(result.g),
        cout_float(result.b)
    );
}

