//! The `HSL` color model and its conversions to and from [`Rgb`].
//!
//! Every intermediate is a single-precision `f32`, and the arithmetic is kept in
//! exactly the order the C++ original uses. That order is load-bearing: hue is
//! derived as a fraction of a turn and only *then* scaled to degrees, so
//! `rgb_to_hsl` rounds at `/6`, at `*360`, and again at the `/360` on the way
//! back. Folding those three steps into a single `*60` is algebraically
//! identical but rounds differently, and the difference is visible — the hue
//! ramp subtracts nearly equal quantities, so a one-ulp shift in hue can move
//! the low digits of a channel by several percent.
//!
//! The same fidelity concern is why results like `0.0200003` and `3.57628e-07`
//! appear instead of a clean `0.02` and `0`.

use crate::rgb::Rgb;

/// A color in the HSL color space.
///
/// `h` is in degrees on `[0, 360)`, while `s` and `l` are normalized to `[0, 1]`
/// for in-gamut input — but, as in the C++ original, nothing enforces that.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Hsl { h, s, l }
    }
}

impl From<Rgb> for Hsl {
    fn from(c: Rgb) -> Hsl {
        rgb_to_hsl(&c)
    }
}

impl From<Hsl> for Rgb {
    fn from(c: Hsl) -> Rgb {
        hsl_to_rgb(&c)
    }
}

/// Converts RGB to HSL.
///
/// Lightness is the midpoint of the channel range, so it is *not* clamped and
/// can leave `[0, 1]` for out-of-gamut input. Saturation divides by a quantity
/// that reaches zero when `max + min == 2`, deliberately yielding an infinity
/// there rather than special-casing it — the caller clamps afterwards.
pub fn rgb_to_hsl(c: &Rgb) -> Hsl {
    let max = c.max_channel();
    let min = c.min_channel();

    let l = (max + min) / 2.0;

    if max == min {
        // Achromatic: hue is undefined, so report the conventional zero.
        return Hsl::new(0.0, 0.0, l);
    }

    let d = max - min;
    let s = if l > 0.5 {
        d / (2.0 - max - min)
    } else {
        d / (max + min)
    };

    // Sector-relative hue in sixths of a turn, normalized to a fraction of a
    // turn, then converted to degrees. Do not collapse `/6` and `*360` into a
    // single `*60`; see the module docs.
    let mut h = if max == c.r {
        (c.g - c.b) / d + if c.g < c.b { 6.0 } else { 0.0 }
    } else if max == c.g {
        (c.b - c.r) / d + 2.0
    } else {
        (c.r - c.g) / d + 4.0
    };
    h /= 6.0;
    h *= 360.0;

    Hsl::new(h, s, l)
}

/// Converts HSL back to RGB.
///
/// With zero saturation every channel collapses onto the lightness. Otherwise
/// the two extremes `p` and `q` are derived from `l` and `s`, and each channel
/// samples the hue ramp at a third-of-a-turn offset.
pub fn hsl_to_rgb(c: &Hsl) -> Rgb {
    if c.s == 0.0 {
        return Rgb::new(c.l, c.l, c.l);
    }

    let q = if c.l < 0.5 {
        c.l * (1.0 + c.s)
    } else {
        c.l + c.s - c.l * c.s
    };
    let p = 2.0 * c.l - q;

    Rgb::new(
        hue_to_rgb(p, q, c.h + 1.0 / 3.0),
        hue_to_rgb(p, q, c.h),
        hue_to_rgb(p, q, c.h - 1.0 / 3.0),
    )
}

/// Samples the piecewise-linear hue ramp between `p` and `q` at position `t`.
///
/// `t` is wrapped into `[0, 1]` by a single additive step in either direction,
/// matching the C++ helper — which is why the wrapped `2/3` boundary lands one
/// ulp away from the literal `2/3` and leaks a tiny residue into blue.
fn hue_to_rgb(p: f32, q: f32, t: f32) -> f32 {
    let mut t = t;
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }

    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

