/// Largest of the three channels, following `std::max({r, g, b})`.
///
/// The comparison keeps the incumbent unless a later channel is *strictly*
/// greater, which is what `std::max_element` does. Writing it the obvious
/// way round (`if r > g { r } else { g }`) agrees for ordinary numbers but
/// diverges on `NaN`: the standard form lets a `NaN` in `r` survive as the
/// maximum and poison the whole conversion, and the C++ program does print
/// `nan nan nan` for a `NaN` red channel.
pub fn max_channel(&self) -> f32 {
    let mut m = self.r;
    if m < self.g {
        m = self.g;
    }
    if m < self.b {
        m = self.b;
    }
    m
}

/// Smallest of the three channels, following `std::min({r, g, b})`; the
/// counterpart of [`Rgb::max_channel`], with the same `NaN` behavior.
pub fn min_channel(&self) -> f32 {
    let mut m = self.r;
    if self.g < m {
        m = self.g;
    }
    if self.b < m {
        m = self.b;
    }
    m
}

