//! The `RGB` color model.
//!
//! Mirrors `ColorSpace::RGB` from the original C++ header: three `float`
//! channels, nominally in `[0, 1]`, stored verbatim without clamping.

/// A color in the RGB color space.
///
/// The constructor performs no range checking, exactly like the C++ original:
/// `RGB(2.0f, -1.0f, 0.5f)` keeps its out-of-gamut channels, and any clamping
/// happens later as a side effect of the conversion math.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }

    /// Largest of the three channels, using plain `<` comparisons so that the
    /// operand order matches `std::max({r, g, b})`.
    pub fn max_channel(&self) -> f32 {
        let m = if self.r > self.g { self.r } else { self.g };
        if m > self.b {
            m
        } else {
            self.b
        }
    }

    /// Smallest of the three channels; the counterpart of [`Rgb::max_channel`].
    pub fn min_channel(&self) -> f32 {
        let m = if self.r < self.g { self.r } else { self.g };
        if m < self.b {
            m
        } else {
            self.b
        }
    }
}

