const SMALLEST_NORMAL: f64 = f32::MIN_POSITIVE as f64;

/// `2^-126 - 2^-151`, the point below which a value stops rounding up to
/// [`SMALLEST_NORMAL`] at 24-bit precision. Needing 26 significand bits, it is
/// exactly representable in `f64`.
const SMALLEST_NORMAL_MIDPOINT: f64 = SMALLEST_NORMAL - SMALLEST_NORMAL / 33_554_432.0;

/// Parses the leading `float` in `s`, reporting `strtof`'s two failure modes.
pub fn parse_float(s: &str) -> Result<f32, ParseFloatError> {
    let bytes = s.as_bytes();
    let mut i = 0;

    // strtof skips leading whitespace before anything else.
    while i < bytes.len() && (bytes[i] as char).is_ascii_whitespace() {
        i += 1;
    }

    let rest = &s[i..];
    let (value, consumed) = scan_number(rest).ok_or(ParseFloatError::Invalid)?;
    if consumed == 0 {
        return Err(ParseFloatError::Invalid);
    }

    let narrowed = value as f32;

    // ERANGE covers both ends of the range, and strtof decides using the value
    // rounded to float's 24-bit significand with an *unbounded* exponent rather
    // than the result it finally stores.
    //
    // Overflow is the easy half: rounding to 24 bits exceeds the largest finite
    // float exactly when narrowing to `f32` gives an infinity. A literal `inf`
    // in the text is not a range error, hence the finiteness guard.
    if narrowed.is_infinite() && value.is_finite() {
        return Err(ParseFloatError::OutOfRange);
    }

    // Underflow is where the two notions come apart, so `narrowed` cannot be
    // consulted. A value just below the smallest normal rounds to a subnormal at
    // 24 bits — an underflow — even though re-rounding it onto the coarser
    // subnormal grid can carry it back up to the smallest normal and hide the
    // evidence. Comparing against the midpoint catches that band, and it also
    // subsumes underflow all the way down to zero.
    if value != 0.0 && value.abs() < SMALLEST_NORMAL_MIDPOINT {
        return Err(ParseFloatError::OutOfRange);
    }

    Ok(narrowed)
}

