//! Reproduction of `std::stof`.
//!
//! `std::stof` is a thin wrapper over `strtof`: it converts the longest valid
//! numeric prefix and ignores whatever follows, throwing `std::invalid_argument`
//! when no conversion is possible and `std::out_of_range` when `strtof` reports
//! `ERANGE`. Both exceptions escape `main` uncaught in the original program, so
//! they surface here as the same `terminate` message on stderr followed by
//! `SIGABRT`.

/// Why a string could not become a `float`.
#[derive(Debug, PartialEq)]
pub enum ParseFloatError {
    /// No numeric prefix at all — `std::invalid_argument`.
    Invalid,
    /// Numerically out of `float`'s range, overflow or underflow — `std::out_of_range`.
    OutOfRange,
}

impl ParseFloatError {
    /// The C++ exception type this maps to, as libstdc++ names it in the
    /// `terminate` banner.
    fn exception_name(&self) -> &'static str {
        match self {
            ParseFloatError::Invalid => "std::invalid_argument",
            ParseFloatError::OutOfRange => "std::out_of_range",
        }
    }
}

/// Parses like `std::stof`, aborting the process on failure the way an uncaught
/// exception would.
pub fn stof(s: &str) -> f32 {
    match parse_float(s) {
        Ok(v) => v,
        Err(e) => {
            eprintln!(
                "terminate called after throwing an instance of '{}'\n  what():  stof",
                e.exception_name()
            );
            std::process::abort();
        }
    }
}

/// Parses the leading `float` in `s`, reporting `strtof`'s two failure modes.
pub fn parse_float(s: &str) -> Result<f32, ParseFloatError> {
    let bytes = s.as_bytes();
    let mut i = 0;

    // strtof skips leading whitespace before anything else.
    while i < bytes.len() && (bytes[i] as char).is_ascii_whitespace() {
        i += 1;
    }

    let rest = &s[i..];
    let (value, consumed) = scan_number(rest).ok_or(ParseFloatError::Invalid)?;
    if consumed == 0 {
        return Err(ParseFloatError::Invalid);
    }

    let narrowed = value as f32;

    // ERANGE covers both ends: overflow to an infinity, and underflow to a
    // subnormal or to zero. A literal infinity or NaN in the text is not a
    // range error, and neither is an exact zero.
    if narrowed.is_infinite() && value.is_finite() {
        return Err(ParseFloatError::OutOfRange);
    }
    if narrowed != 0.0 && narrowed.abs() < f32::MIN_POSITIVE {
        return Err(ParseFloatError::OutOfRange);
    }
    if narrowed == 0.0 && value != 0.0 {
        return Err(ParseFloatError::OutOfRange);
    }

    Ok(narrowed)
}

/// Scans one numeric token, returning its value and the bytes consumed.
///
/// Accumulates in `f64` so that narrowing to `f32` at the end reproduces
/// `strtof`'s single rounding for every input a `float` can distinguish.
fn scan_number(s: &str) -> Option<(f64, usize)> {
    let bytes = s.as_bytes();
    let mut i = 0;

    let negative = match bytes.first() {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let magnitude = &s[i..];
    let (value, consumed) = scan_infinity(magnitude)
        .or_else(|| scan_nan(magnitude))
        .or_else(|| scan_hex(magnitude))
        .or_else(|| scan_decimal(magnitude))?;

    Some((if negative { -value } else { value }, i + consumed))
}

/// Matches `inf` or `infinity`, case-insensitively, preferring the longer form.
fn scan_infinity(s: &str) -> Option<(f64, usize)> {
    for form in ["infinity", "inf"] {
        if s.len() >= form.len() && s[..form.len()].eq_ignore_ascii_case(form) {
            return Some((f64::INFINITY, form.len()));
        }
    }
    None
}

/// Matches `nan`, plus the optional `n-char-sequence` in parentheses.
fn scan_nan(s: &str) -> Option<(f64, usize)> {
    if s.len() < 3 || !s[..3].eq_ignore_ascii_case("nan") {
        return None;
    }
    let mut consumed = 3;

    let bytes = s.as_bytes();
    if bytes.get(3) == Some(&b'(') {
        let mut j = 4;
        while j < bytes.len() && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') {
            j += 1;
        }
        // Only count the tail if it is actually closed.
        if bytes.get(j) == Some(&b')') {
            consumed = j + 1;
        }
    }

    Some((f64::NAN, consumed))
}

/// Matches a C99 hex float: `0x` digits `[. digits] [p exponent]`.
///
/// The binary exponent is optional for `strtof` even though C99 requires it,
/// and glibc accepts `0x1` as simply `1`.
fn scan_hex(s: &str) -> Option<(f64, usize)> {
    let bytes = s.as_bytes();
    if bytes.len() < 2 || bytes[0] != b'0' || (bytes[1] | 0x20) != b'x' {
        return None;
    }

    let mut i = 2;
    let mut mantissa = 0.0f64;
    let mut digits = 0;
    while i < bytes.len() {
        if let Some(d) = (bytes[i] as char).to_digit(16) {
            mantissa = mantissa * 16.0 + d as f64;
            digits += 1;
            i += 1;
        } else {
            break;
        }
    }

    // Fractional hex digits each shift the value down by four bits.
    let mut binary_exp = 0i32;
    if i < bytes.len() && bytes[i] == b'.' {
        let mut j = i + 1;
        while j < bytes.len() {
            if let Some(d) = (bytes[j] as char).to_digit(16) {
                mantissa = mantissa * 16.0 + d as f64;
                binary_exp -= 4;
                digits += 1;
                j += 1;
            } else {
                break;
            }
        }
        // A lone "0x." is not a number; only advance past the point if it had
        // digits on one side or the other.
        if digits > 0 {
            i = j;
        }
    }

    if digits == 0 {
        return None;
    }

    // "0x1p3" — the exponent only counts if it is well formed.
    if i < bytes.len() && (bytes[i] | 0x20) == b'p' {
        if let Some((exp, used)) = scan_exponent(&s[i + 1..]) {
            binary_exp += exp;
            i += 1 + used;
        }
    }

    Some((mantissa * pow2(binary_exp), i))
}

/// Matches a decimal float: digits with an optional point and optional `e` exponent.
fn scan_decimal(s: &str) -> Option<(f64, usize)> {
    let bytes = s.as_bytes();
    let mut i = 0;

    let int_start = i;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    let int_digits = i - int_start;

    let mut frac_digits = 0;
    let mut end_of_significand = i;
    if i < bytes.len() && bytes[i] == b'.' {
        let mut j = i + 1;
        while j < bytes.len() && bytes[j].is_ascii_digit() {
            j += 1;
        }
        frac_digits = j - (i + 1);
        // "1." is valid, and so is ".5", but a bare "." is not.
        if int_digits > 0 || frac_digits > 0 {
            end_of_significand = j;
            i = j;
        }
    }

    if int_digits == 0 && frac_digits == 0 {
        return None;
    }

    let significand = &s[..end_of_significand];

    if i < bytes.len() && (bytes[i] | 0x20) == b'e' {
        if let Some((exp, used)) = scan_exponent(&s[i + 1..]) {
            let end = i + 1 + used;
            // Hand the whole token to the standard parser so the significand and
            // exponent are combined with a single correct rounding.
            let value = format!("{}e{}", significand, exp).parse::<f64>().ok()?;
            return Some((value, end));
        }
    }

    Some((significand.parse::<f64>().ok()?, i))
}

/// Matches a decimal exponent tail: an optional sign followed by digits.
///
/// Returns `None` when no digits follow, so that `"1e"` parses as just `1` with
/// the `e` left unconsumed.
fn scan_exponent(s: &str) -> Option<(i32, usize)> {
    let bytes = s.as_bytes();
    let mut i = 0;

    let negative = match bytes.first() {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let digits_start = i;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    if i == digits_start {
        return None;
    }

    // Saturate absurd exponents; they only have to push the result past a
    // float's range, and the caller turns that into out_of_range.
    let exp = s[digits_start..i].parse::<i64>().unwrap_or(i64::MAX);
    let exp = exp.min(i32::MAX as i64 / 2) as i32;

    Some((if negative { -exp } else { exp }, i))
}

/// Computes `2^exp` without overflowing intermediate values for large `|exp|`.
fn pow2(exp: i32) -> f64 {
    if exp >= 0 {
        (0..exp).fold(1.0f64, |acc, _| {
            if acc.is_infinite() {
                acc
            } else {
                acc * 2.0
            }
        })
    } else {
        (0..-exp).fold(1.0f64, |acc, _| if acc == 0.0 { acc } else { acc / 2.0 })
    }
}

